[{"fieldname": "print_heading_template", "fieldtype": "Custom HTML", "options": "<div class="print-heading">				<h2><div>Employee</div><br><small class="sub-heading">{{ _(doc.name) }}</small>				</h2></div>"}, {"fieldtype": "Section Break", "label": ""}, {"fieldtype": "Column Break"}, {"fieldname": "_custom_html", "print_hide": 0, "label": "Custom HTML", "fieldtype": "HTML", "options": "<link rel="preconnect" href="https://fonts.googleapis.com">
<link rel="preconnect" href="https://fonts.gstatic.com" crossorigin>
<link href="https://fonts.googleapis.com/css2?family=Noto+Nastaliq+Urdu:wght@400;500;600;700&display=swap" rel="stylesheet">

{% set employee_id = doc.name %}
{% set employee_name = doc.get("employee_name") or doc.get("full_name") or doc.name %}
{% set father_name = doc.get("custom_father_name") or doc.get("father_name") or "-" %}
{% set current_address = doc.get("current_address") or "-" %}
{% set permanent_address = doc.get("permanent_address") or "-" %}
{% set phone = doc.get("cell_number") or doc.get("personal_phone") or "-" %}
{% set cnic = doc.get("custom_cnic") or doc.get("cnic") or doc.get("passport_number") or "-" %}
{% set branch = doc.get("branch") or "-" %}
{% set teaching_type = doc.get("custom_teaching_type") or "-" %}
{% set appointment_date = doc.get("date_of_joining") or frappe.utils.today() %}
{% set print_date = frappe.utils.today() %}
{% set islamic_date = (doc.get("custom_hijri_date") | string).replace("-", "/") if doc.get("custom_hijri_date") else "-" %}

{% set shift_rows = frappe.get_all(
    "Shift Assignment",
    filters={"employee": employee_id, "status": "Active"},
    fields=["shift_type", "shift_location"],
    order_by="start_date desc",
    limit_page_length=1
) %}
{% set shift = shift_rows[0] if shift_rows else None %}
{% set shift_type = shift.shift_type if shift and shift.shift_type else "-" %}
{% set shift_location = shift.shift_location if shift and shift.shift_location else "-" %}
{% set duty_time = shift_type %}

{% set modern_education = namespace(value="-") %}
{% set education_rows = doc.get("education") or [] %}
{% if education_rows and education_rows[0].qualification %}
    {% set modern_education.value = education_rows[0].qualification %}
{% endif %}

{% set religious_education = namespace(value="-") %}
{% set religious_rows = doc.get("custom_religious_qualification") or [] %}
{% if religious_rows and religious_rows[0].qualification %}
    {% set religious_education.value = religious_rows[0].qualification %}
{% endif %}

{% set ns = namespace(basic=0, medical=0, other=0) %}
{% for row in doc.get("custom_employee_earnings") or [] %}
    {% set component = (row.salary_component or "").lower() %}
    {% if "basic" in component %}
        {% set ns.basic = row.amount or 0 %}
    {% elif "medical" in component %}
        {% set ns.medical = row.amount or 0 %}
    {% elif "other allowance" in component or "other" in component %}
        {% set ns.other = row.amount or 0 %}
    {% endif %}
{% endfor %}
{% set total_salary = ns.basic + ns.medical + ns.other %}

{% macro rs_amount(value) %}
Rs {{ frappe.utils.fmt_money(value or 0, currency=None) }}
{% endmacro %}
{# Builder Custom HTML receives only doc, so fetch the requested Letter Head explicitly. #}
{% set hide_letter_head = frappe.form_dict and frappe.form_dict.get("no_letterhead") in [1, "1", true, "true", "True"] %}
{% set selected_letter_head_name = frappe.form_dict.get("letterhead") if frappe.form_dict and not hide_letter_head else None %}

{% if not hide_letter_head and not selected_letter_head_name and doc.get("company") %}
    {% set selected_letter_head_name = frappe.db.get_value("Company", doc.company, "default_letter_head") %}
{% endif %}

{% if not hide_letter_head and not selected_letter_head_name %}
    {% set selected_letter_head_name = frappe.db.get_value("Letter Head", {"is_default": 1, "disabled": 0}, "name") %}
{% endif %}

{% set selected_letter_head = frappe.get_doc("Letter Head", selected_letter_head_name) if selected_letter_head_name else None %}
{% set repeated_header = frappe.render_template(selected_letter_head.content, {"doc": doc}) if selected_letter_head and selected_letter_head.content else "" %}
{% set repeated_footer = frappe.render_template(selected_letter_head.footer, {"doc": doc}) if selected_letter_head and selected_letter_head.footer else "" %}
{% set has_letter_head = repeated_header and not hide_letter_head %}

<style>
.print-heading,
.print-format h1:first-child,
.print-format .page-break > h1:first-child {
    display: none !important;
}

@page {
    size: A4 portrait;
    margin: 0;
}

.print-format {
    padding: 0 !important;
    margin: 0 !important;
}

.print-format .section-break,
.print-format .column-break {
    margin: 0 !important;
    padding: 0 !important;
}

/* The standard header/footer are rendered inside jtq-sheet below. */
.letter-head,
.letter-head-footer {
    display: none !important;
}

.jtq-sheet {
    position: relative;
    width: 210mm;
    min-height: 0;
    height: auto;
    margin: 0 auto;
    padding: 7mm 9mm;
    box-sizing: border-box;
    overflow: visible;
}

/* 44mm plus the 7mm sheet padding reserves the 2-inch printed header. */
.jtq-sheet.without-letter-head {
    padding-top: 48mm;
}

.jtq-system-header {
    width: 100%;
    margin: 0 auto 2mm;
    padding: 0;
    text-align: center;
}

.jtq-system-header img {
    display: block;
    width: 100% !important;
    max-width: 100% !important;
    height: auto !important;
    margin: 0 auto !important;
}

.jtq-system-footer {
    width: 100%;
    margin-top: 2mm;
    text-align: center;
}

.jtq-system-footer img {
    display: block;
    width: 100% !important;
    max-width: 100% !important;
    max-height: 17mm !important;
    height: auto !important;
    margin: 0 auto !important;
}

.jtq-letter {
    width: 195mm;
    margin-left: auto;
    margin-right: auto;
    margin-bottom: -30px;
    margin-top: 40px;
    direction: rtl;
    font-family: "Noto Nastaliq Urdu", "Nafees Nastaleeq", "Jameel Noori Nastaleeq", "Noto Naskh Arabic", Arial, sans-serif;
    color: #000;
    font-size: 11px;
    line-height: inherit;
    text-align: center;
}

.jtq-title {
    background: #000;
    color: #fff;
    width: 39%;
    margin: 0 auto 6px auto;
    padding: 4px 0 6px 0;
    min-height: 30px;
    line-height: 1.2;
    text-align: center;
    font-size: 15px;
    font-weight: 300;
}

.jtq-grid {
    width: 100%;
}

.jtq-row {
    display: flex;
    direction: rtl;
    width: 100%;
    box-sizing: border-box;
    margin-bottom: 4px;
}

.jtq-field {
    display: flex;
    align-items: flex-end;
    box-sizing: border-box;
    padding: 4px 5px;
    height: 22px;
    min-width: 0;
}

.jtq-field.wrap {
    height: auto;
    min-height: 22px;
    align-items: flex-start;
}

.jtq-field-label {
    flex: 0 0 auto;
    white-space: nowrap;
    font-weight: bold;
    padding-left: 6px;
    line-height: 20px;
}

.jtq-field-value {
    flex: 1 1 auto;
    min-width: 0;
    border-bottom: 1px solid #000;
    text-align: center;
    font-weight: bold;
    overflow: hidden;
    white-space: nowrap;
    height: 20px;
    line-height: 20px;
    padding: 0 6px;
    box-sizing: border-box;
}

.jtq-letter .jtq-field-value[lang="en"] {
    font-size: 10px !important;
}

.jtq-field-value.wrap {
    white-space: normal;
    height: auto;
    min-height: 20px;
    line-height: 1.6;
    padding: 2px 6px;
}


.jtq-row-3 > .jtq-field { flex: 0 0 33.3333%; }
.jtq-row-2 > .jtq-field { flex: 0 0 50%; }
.jtq-row-4 > .jtq-field { flex: 0 0 25%; }

.jtq-note {
    margin-top: 9px;
    padding-right: 6px;
    font-size: 8.5px;
    font-weight: bold;
    text-align: right;
    line-height: 1;
}

.jtq-manager {
    width: 140px;
    margin-top: 34px;
    margin-left: 6px;
    margin-right: auto;
    text-align: center;
    direction: rtl;
    font-size: 11px;
    font-weight: bold;
}

.jtq-sign-line {
    border-top: 0.5px solid #000;
    height: 5px;
    margin-bottom: 1px;
}

.jtq-instructions-wrap {
    margin-top: 7px;
}

.jtq-instructions-heading {
    width: 100%;
    table-layout: fixed;
    border-collapse: collapse;
    margin-top: 0.5px;
    margin-bottom: 6px;
}

.jtq-instructions-heading td {
    vertical-align: middle;
    padding: 0;
}

.jtq-heading-line div {
    border-top: 0.5px solid #000;
    height: 0;
    line-height: 0;
}

.jtq-heading-text {
    width: 100px;
    text-align: center;
    font-size: 11px;
    font-weight: bold;
    white-space: nowrap;
    line-height: 0;
}

.jtq-instructions {
    direction: rtl;
    text-align: right;
    font-size: 10px;
    line-height: 1.5;
}

.jtq-instructions div {
    margin-bottom: 2px;
}

.jtq-confirm-wrap {
    width: 30%;
    margin-top: 4px;
    margin-left: 0;
    margin-right: auto;
    text-align: right;
    direction: rtl;
}

.jtq-confirm-line {
    background: #d9e2e8;
    padding: 4px 15px;
    font-size: 7.5px;
    line-height: 1;
}

.jtq-copy-section {
    margin-top: 16px;
    page-break-inside: avoid;
}

.jtq-copy-table {
    width: 100%;
    border-collapse: collapse;
    table-layout: fixed;
    direction: ltr;
}

.jtq-sign-cell {
    width: 4%;
    text-align: left;
    vertical-align: bottom;
    padding-left: 16px;
}

.jtq-sign-box {
    width: 130px;
    padding-top: 38px;
    text-align: center;
    direction: rtl;
    font-size: 9px;
    font-weight: bold;
}

.jtq-copy-cell {
    width: 15%;
    text-align: right;
    vertical-align: top;
    padding-top: 16px;
    direction: rtl;
    font-size: 9px;
    font-weight: bold;
}

.jtq-copy-title {
    text-decoration: underline;
    margin-bottom: 10px;
}

.jtq-copy-items {
    white-space: nowrap;
}
</style>

<div class="jtq-sheet {% if has_letter_head %}with-letter-head{% else %}without-letter-head{% endif %}">

    {% if has_letter_head %}
        <div class="jtq-system-header">
            {{ repeated_header | safe }}
        </div>
    {% endif %}

<div class="jtq-letter">

    <div class="jtq-title"> آزمائشی تقرر نامہ برائے معلم / معلمہ</div>

    <div class="jtq-grid">

        <div class="jtq-row jtq-row-3">
            <div class="jtq-field">
                <span class="jtq-field-label">فائل نمبر:</span>
                <span class="jtq-field-value" lang="en">{{ doc.get("custom_file_no") or employee_id }}</span>
            </div>
            <div class="jtq-field">
                <span class="jtq-field-label">کوڈ نمبر:</span>
                <span class="jtq-field-value" lang="en">{{ doc.get("custom_code_no") or employee_id }}</span>
            </div>
            <div class="jtq-field">
                <span class="jtq-field-label">تاریخ:</span>
                <span class="jtq-field-value" lang="en">{{ frappe.utils.formatdate(print_date, "dd/MM/yyyy") }}</span>
            </div>
        </div>

        <div class="jtq-row jtq-row-3">
            <div class="jtq-field">
                <span class="jtq-field-label">محترم / محترمہ:</span>
                <span class="jtq-field-value" lang="en">{{ employee_name }}</span>
            </div>
            <div class="jtq-field">
                <span class="jtq-field-label">ولدیت:</span>
                <span class="jtq-field-value" lang="en">{{ father_name }}</span>
            </div>
            <div class="jtq-field">
                <span class="jtq-field-label">شناختی کارڈ نمبر:</span>
                <span class="jtq-field-value" lang="en">{{ cnic }}</span>
            </div>
        </div>

        <div class="jtq-row jtq-row-2">
            <div class="jtq-field wrap">
                <span class="jtq-field-label">موجودہ پتہ:</span>
                <span class="jtq-field-value wrap" lang="en">{{ current_address }}</span>
            </div>
            <div class="jtq-field wrap">
                <span class="jtq-field-label">مستقل پتہ:</span>
                <span class="jtq-field-value wrap" lang="en">{{ permanent_address }}</span>
            </div>
        </div>

        <div class="jtq-row jtq-row-3">
            <div class="jtq-field">
                <span class="jtq-field-label">رابطہ نمبر:</span>
                <span class="jtq-field-value" lang="en">{{ phone }}</span>
            </div>
            <div class="jtq-field">
                <span class="jtq-field-label">اکاؤنٹ نمبر:</span>
                <span class="jtq-field-value" lang="en">{{ doc.get("bank_ac_no") or "-" }}</span>
            </div>
            <div class="jtq-field">
                <span class="jtq-field-label">بینک کا نام:</span>
                <span class="jtq-field-value" lang="en">{{ doc.get("bank_name") or "-" }}</span>
            </div>
        </div>

        <div class="jtq-row jtq-row-2">
            <div class="jtq-field wrap">
                <span class="jtq-field-label">دینی تعلیم:</span>
                <span class="jtq-field-value wrap" lang="en">{{ religious_education.value }}</span>
            </div>
            <div class="jtq-field wrap">
                <span class="jtq-field-label">عصری تعلیم:</span>
                <span class="jtq-field-value wrap" lang="en">{{ modern_education.value }}</span>
            </div>
        </div>

        <div class="jtq-row jtq-row-3">
            <div class="jtq-field">
                <span class="jtq-field-label">تاریخ تقرر:</span>
                <span class="jtq-field-value" lang="en">{{ frappe.utils.formatdate(appointment_date, "dd/MM/yyyy") }}</span>
            </div>
            <div class="jtq-field">
                <span class="jtq-field-label">مطابق:</span>
                <span class="jtq-field-value" lang="en">{{ islamic_date }}</span>
            </div>
            <div class="jtq-field">
                <span class="jtq-field-label">مقام تقرر:</span>
                <span class="jtq-field-value" lang="en">{{ shift_location }}</span>
            </div>
        </div>

        <div class="jtq-row jtq-row-3">
            <div class="jtq-field">
                <span class="jtq-field-label">شاخ / حلقہ:</span>
                <span class="jtq-field-value" lang="en">{{ branch }}</span>
            </div>
            <div class="jtq-field">
                <span class="jtq-field-label">درجہ:</span>
                <span class="jtq-field-value" lang="en">{{ teaching_type }}</span>
            </div>
            <div class="jtq-field">
                <span class="jtq-field-label">اوقات کار:</span>
                <span class="jtq-field-value" lang="en">{{ duty_time }}</span>
            </div>
        </div>

        <div class="jtq-row jtq-row-4">
            <div class="jtq-field">
                <span class="jtq-field-label">رقم ماہانہ مشاہرہ:</span>
                <span class="jtq-field-value" lang="en">{{ rs_amount(ns.basic) }}</span>
            </div>
            <div class="jtq-field">
                <span class="jtq-field-label">میڈیکل الاؤنس:</span>
                <span class="jtq-field-value" lang="en">{{ rs_amount(ns.medical) }}</span>
            </div>
            <div class="jtq-field">
                <span class="jtq-field-label">دیگر الاؤنس:</span>
                <span class="jtq-field-value" lang="en">{{ rs_amount(ns.other) }}</span>
            </div>
            <div class="jtq-field">
                <span class="jtq-field-label">کل رقم:</span>
                <span class="jtq-field-value" lang="en">{{ rs_amount(total_salary) }}</span>
            </div>
        </div>

    </div>

    <div class="jtq-note">
        نوٹ: دیگر الاؤنس / مراعات آزمائشی تقرر مکمل ہونے اور مستقل تقرری پر لاگو ہونگے۔
    </div>

    <div class="jtq-manager">
        <div class="jtq-sign-line"></div>
        <div>مینیجر ایچ آر</div>
    </div>

    <div class="jtq-instructions-wrap">
        <table class="jtq-instructions-heading">
            <tr>
                <td class="jtq-heading-line"><div></div></td>
                <td class="jtq-heading-text">ضروری ہدایات</td>
                <td class="jtq-heading-line"><div></div></td>
            </tr>
        </table>

        <div class="jtq-instructions">
            <div>* آپ کا تقرر آزمائشی ہے جس کی مدت چھ ماہ ہے۔ یہ مدت پوری ہونے پر ادارہ کی طرف سے کوئی شکایت نہ ہوئی تو یہ تقرر نامہ مستقل تصور ہو گا۔</div>
            <div>* ادارے کے قواعد و ضوابط پر عمل نہ کرنے یا غیر اخلاقی حرکت کا مرتکب ہونے پر مطلوبہ کارروائی کی جائے گی جو سبکدوشی کا باعث بن سکتی ہے۔</div>
            <div>* مستقل و آزمائشی تقرر کے دوران کسی بھی جگہ تعیناتی / تبادلہ کا مکمل اختیار ادارہ کا ہو گا اور مقرری اس کا پابند ہو گا۔</div>
            <div>* مستقل تقرری پر اگر آپ ادارہ سے فارغ ہونا چاہیں تو کم از کم ایک ماہ کا نوٹس دیں گے اور ادارہ کی صوابدید پر مقررہ مدت پوری کرنا لازم ہو گا۔ نوٹس کے بغیر مستعفی ہونے کی صورت میں ایک ماہ مشاہرہ آپ کے ذمہ واجب الادا ہو گا۔</div>
            <div>* اگر ادارہ آپ سے مزید خدمات نہیں لینا چاہتا تو آپ کو ایک ماہ کے نوٹس پر یا ایک ماہ کا مشاہرہ بطور نوٹس ادا کر کے فارغ کر سکتا ہے۔</div>
            <div>* آزمائشی تقرر کے دوران رخصت خلاف ضابطہ ہے، البتہ کسی ایمرجنسی کی صورت اطلاع دے کر ایک یوم کی رخصت کی اجازت ہو گی۔</div>
            <div>* اگر تقرر کے وقت بینک اکاؤنٹ تفصیل نہیں دی ہے تو ایک ہفتہ میں جمع کروانا ضروری ہے تاکہ مشاہرہ براہ راست اکاؤنٹ میں منتقل کیا جا سکے۔ بصورت دیگر مشاہرہ کی ادائیگی بذریعہ چیک کی جائے گی۔</div>
            <div>* تمام الاؤنس / مراعات مستقل تقرری پر ہی لاگو ہونگے۔</div>
        </div>

        <div class="jtq-confirm-wrap">
            <div class="jtq-confirm-line">میں اقرار کرتا / کرتی ہوں کہ میں نے تمام ہدایات اور ذمہ داریوں کی تفصیل</div>
            <div class="jtq-confirm-line">منسلک کو بغور پڑھ اور سمجھ لیا، ان شاء اللہ حتی الامکان عمل کروں گا / گی۔</div>
        </div>
    </div>

    <div class="jtq-copy-section">
        <table class="jtq-copy-table">
            <tr>
                <td class="jtq-sign-cell">
                    <div class="jtq-sign-box">
                        <div class="jtq-sign-line"></div>
                        <div>دستخط</div>
                    </div>
                </td>

                <td class="jtq-copy-cell">
                    <div class="jtq-copy-title">کاپی برائے:</div>
                    <div class="jtq-copy-items">
                        دفتر نظامت &nbsp; * &nbsp; شعبہ حسابات &nbsp; * &nbsp; آفس فائل &nbsp; * &nbsp; معلم / معلمہ
                    </div>
                </td>
            </tr>
        </table>
    </div>

</div>
<br><br><br><br><br><br><br><br>
    {% if has_letter_head and repeated_footer %}
        <div class="jtq-system-footer">
            {{ repeated_footer | safe }}
        </div>
    {% endif %}

</div>
"}]

[{"fieldname": "print_heading_template", "fieldtype": "Custom HTML", "options": "<div class="print-heading">				<h2><div>Employee</div><br><small class="sub-heading">{{ _(doc.name) }}</small>				</h2></div>"}, {"fieldtype": "Section Break", "label": ""}, {"fieldtype": "Column Break"}, {"fieldname": "_custom_html", "print_hide": 0, "label": "Custom HTML", "fieldtype": "HTML", "options": "{% set employee_id = doc.name if doc.doctype == "Employee" else (doc.get("employee") or doc.get("employee_id") or doc.get("custom_employee")) %}

{% if not employee_id and doc.get("job_applicant") %}
    {% set employee_id = frappe.db.get_value("Employee", {"job_applicant": doc.job_applicant}, "name") %}
{% endif %}

{% if not employee_id and doc.get("applicant_name") %}
    {% set employee_id = frappe.db.get_value("Employee", {"employee_name": doc.applicant_name}, "name") %}
{% endif %}

{% set employee = frappe.get_doc("Employee", employee_id) if employee_id else None %}

{% set employee_name = employee.employee_name if employee and employee.employee_name else (doc.get("applicant_name") or doc.get("employee_name") or doc.name) %}
{% set salutation = employee.salutation if employee and employee.salutation else (doc.get("salutation") or "") %}
{% set employee_address = employee.current_address if employee and employee.current_address else (doc.get("current_address") or "") %}
{% set designation = employee.designation if employee and employee.designation else (doc.get("designation") or "-") %}
{% set department = employee.department if employee and employee.department else (doc.get("department") or "Education") %}
{% set company = employee.company if employee and employee.company else doc.get("company") %}
{% set company_abbr = frappe.db.get_value("Company", company, "abbr") if company else "" %}
{% set joining_date = employee.date_of_joining if employee and employee.date_of_joining else (doc.get("appointment_date") or doc.creation) %}
{% set appointment_date = doc.get("appointment_date") or joining_date %}

{# The Builder block does not receive letter_head/footer directly. #}
{% set suppress_letter_head = frappe.form_dict and frappe.form_dict.get("no_letterhead") in [1, "1", true, "true", "True"] %}
{% set selected_letter_head_name = frappe.form_dict.get("letterhead") if frappe.form_dict and not suppress_letter_head else None %}
{% if not suppress_letter_head and not selected_letter_head_name and company %}
    {% set selected_letter_head_name = frappe.db.get_value("Company", company, "default_letter_head") %}
{% endif %}
{% if not suppress_letter_head and not selected_letter_head_name %}
    {% set selected_letter_head_name = frappe.db.get_value("Letter Head", {"is_default": 1}, "name") %}
{% endif %}
{% set selected_letter_head = frappe.get_doc("Letter Head", selected_letter_head_name) if selected_letter_head_name else None %}
{% set repeated_header = frappe.render_template(selected_letter_head.content, {"doc": doc}) if selected_letter_head and selected_letter_head.content else "" %}
{% set repeated_footer = frappe.render_template(selected_letter_head.footer, {"doc": doc}) if selected_letter_head and selected_letter_head.footer else "" %}

{% set department_clean = (department or "")|string|trim %}
{% if company_abbr %}
    {% set department_clean = department_clean.replace(" - " ~ company_abbr, "") %}
    {% set department_clean = department_clean.replace("- " ~ company_abbr, "") %}
    {% set department_clean = department_clean.replace("-" ~ company_abbr, "") %}
{% endif %}
{% if " - " in department_clean %}
    {% set department_clean = department_clean.split(" - ")[0] %}
{% endif %}
{% if "department" not in department_clean|lower %}
    {% set department_clean = department_clean ~ " Department" %}
{% endif %}

{% set salary = namespace(basic=0, medical=0) %}
{% if employee_id %}
    {% set earning_rows = frappe.get_all(
        "Employee Salary Component Detail",
        filters={
            "parent": employee_id,
            "parenttype": "Employee",
            "parentfield": "custom_employee_earnings"
        },
        fields=["salary_component", "amount"],
        limit_page_length=100
    ) %}

    {% for row in earning_rows %}
        {% set component = (row.salary_component or "")|lower|trim %}
        {% if "basic" in component %}
            {% set salary.basic = row.amount or 0 %}
        {% elif "medical" in component %}
            {% set salary.medical = row.amount or 0 %}
        {% endif %}
    {% endfor %}
{% endif %}

<style>
@page {
    size: A4 portrait;
    margin: 0;
}

